module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

    reg [3:0] cnt;
    reg start_cnt;
    reg res_valid_reg;
    reg [8:0] neg_divisor;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [15:0] result_reg;
    reg [17:0] SR;

    always @(posedge clk or negedge rst) begin
        if(!rst) begin
            cnt <= 4'd0;
            start_cnt <= 1'b1;
            res_valid_reg <= 1'b0;
            neg_divisor <= 9'd0;
            dividend_abs <= 8'd0;
            divisor_abs <= 8'd0;
            result_reg <= 16'd0;
            SR <= 18'd0;
        end
        else begin
            if(opn_valid && !res_valid_reg) begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;

                neg_divisor <= ~{1'b0, divisor_abs} + 9'd1;

                SR <= {1'b0, dividend_abs << 1};

                cnt <= 4'd1;
                start_cnt <= 1'b1;
            end

            if(start_cnt) begin
                if(cnt[3]) begin
                    cnt <= 4'd0;
                    start_cnt <= 1'b0;

                    result_reg <= {SR[17:0], 1'b0};
                end
                else begin
                    cnt <= cnt + 4'd1;

                    SR <= {SR[16:0], SR[17]};
                end
            end
        end
    end

    assign res_valid = res_valid_reg;
    assign result = result_reg;

    always @(posedge clk or negedge rst) begin
        if(!rst) begin
            res_valid_reg <= 1'b0;
        end
        else begin
            if(cnt == 4'd8) begin
                res_valid_reg <= 1'b1;
            end
            else if(res_valid_reg & res_ready) begin
                res_valid_reg <= 1'b0;
            end
            else begin
                res_valid_reg <= res_valid_reg;
            end
        end
    end
endmodule
